/**
 * Pose registry for the image-based character. Availability comes from the
 * manifest generated by `npm run assets:character` — dropping a new render in
 * assets-src/character/poses/ and re-running the script is all it takes.
 */
import manifest from '../../../public/images/character/poses/manifest.json';

export type PoseId =
  | '01-standing'
  | '02-laptop-working'
  | '03-preparing-to-stand'
  | '04-jumping'
  | '05-pushing-computer'
  | '06-desktop-working'
  | '07-landing'
  | '08-confident-standing'
  | '09-superhero-jump'
  | '10-presenting-work'
  | '11-writing'
  | '12-waving';

type UV = [number, number];

export interface RigDef {
  joints: Record<string, UV>;
  crotchX: number;
  arms: { L: UV[]; R: UV[] };
  /** Per-cell part map from asset prep: '.' empty, '0' body, '1' left arm, '2' right arm. */
  parts?: { cols: number; rows: number; data: string };
  /** Synthesised torso behind the sleeves (asset prep): drawn under the arms so a swinging arm uncovers fabric. */
  underlay?: { src: string; cells: string } | null;
}

export interface PoseAsset {
  id: PoseId;
  src: string;
  width: number;
  height: number;
  aspect: number;
  worldWidth: number;
  worldHeight: number;
  anchor: 'feet' | 'hips';
  anchors: { feet?: UV; hips?: UV };
  head: { crown: UV; chin: UV } | null;
  rig: RigDef | null;
}

const assets = new Map<string, PoseAsset>((manifest.poses as unknown as PoseAsset[]).map((p) => [p.id, p]));

export const BASE_POSE: PoseId = '01-standing';
export const missingPoses = (manifest.missing as { id: string; expectedSource: string }[]).map((m) => m.id);

export const hasPose = (id: PoseId) => assets.has(id);
export function getPose(id: PoseId): PoseAsset {
  return assets.get(id) ?? assets.get(BASE_POSE)!;
}
/** First available pose from a preference list, else the base pose. */
export function pickPose(prefs: readonly PoseId[]): PoseId {
  for (const id of prefs) if (assets.has(id)) return id;
  return BASE_POSE;
}

/** Pelvis → sole distance of the base pose (metres), for hip/feet anchoring maths. */
export function baseLegLength() {
  const p = getPose(BASE_POSE);
  const pelvis = p.rig?.joints.pelvis ?? p.anchors.hips ?? [0.5, 0.55];
  const feet = p.anchors.feet ?? [0.5, 1];
  return (feet[1] - pelvis[1]) * p.worldHeight;
}
